import React, { useEffect, useState } from "react";
import { CustomFormItem, CustomInput } from "../../../components";
import useApi from "../../../hooks/useApi";
import dependantsApi from "../../../api/dependantsApi";
import { Button, Divider, Flex, Radio, Table } from "antd";
import hospitalsApi from "../../../api/hospitals/hospitalsApi";
import { toast, ToastContainer } from "react-toastify";
import { useStateContext } from "../../../contexts/ContextProvider";
import DepartmentToReferModal from "./DepartmentToReferModal";
import { useNavigate } from "react-router-dom";

export default function InpatientList() {
  const [searchText, setsearchText] = useState("");
  const [departmentalVisitors, setDepartmentalVisitors] = useState([]);
  const [selectedDepartmentalVisit, setselectedDepartmentalVisit] = useState();
  const { currentColor } = useStateContext();
  const [data, setdata] = useState([]);
  const [openDepartmentToReferModal, setopenDepartmentToReferModal] =
    useState(false);
  const navigate = useNavigate();

  const columns = [
    {
      title: "Names",
      dataIndex: "dependant_title",
      render: (text) => <a>{text}</a>,
    },
    {
      title: "Date of Birth",
      dataIndex: "dependant_dob",
      render: (text) => <a>{text}</a>,
    },
    {
      title: "Age",
      dataIndex: "dependant_age",
    },
    {
      title: "Gender",
      dataIndex: "dependant_gender",
    },
    {
      title: "Department",
      dataIndex: "department_title",
    },
    {
      title: "Time In",
      dataIndex: "checkin_time",
    },
    {
      title: "Time Out",
      dataIndex: "checkout_time",
    },
  ];
  const departmentalVisitorsApi = useApi(hospitalsApi.hospitalStaffAction);

  const getDepartmentalVisitors = async (text) => {
    await departmentalVisitorsApi.request({
      action: "GetAllDepartmentalVisits",
    });
  };

  useEffect(() => {
    if (departmentalVisitorsApi.data && departmentalVisitorsApi.data.length) {
      setDepartmentalVisitors(departmentalVisitorsApi.data);
    }
    console.log("departmentalVisitorsApi.data", departmentalVisitorsApi.data);
  }, [departmentalVisitorsApi.data]);

  useEffect(() => {
    getDepartmentalVisitors();
  }, []);

  useEffect(() => {
    setdata(departmentalVisitors);
  }, [departmentalVisitors]);

  const [selectedRowKeys, setSelectedRowKeys] = useState([]);

  const onSelectChange = (newSelectedRowKeys, selectedRows) => {
    console.log("selectedRowKeys changed: ", newSelectedRowKeys);
    setSelectedRowKeys(newSelectedRowKeys);
    setselectedDepartmentalVisit(selectedRows[0]);
  };

  const rowSelection = {
    selectedRowKeys,
    onChange: onSelectChange,
  };

  useEffect(() => {
    if (selectedRowKeys && selectedRowKeys.length === 1) {
      navigate(`/hospitals/inpatient/dashboard`, {
        state: {
          dependant: selectedDepartmentalVisit.dependant,
          department: selectedDepartmentalVisit.department,
          visit: selectedDepartmentalVisit.id,
        },
      });
    } else {
      return;
    }
  }, [selectedRowKeys]);

  const hasSelected = selectedRowKeys.length > 0;
  const [loading, setLoading] = useState(false);
  const start = () => {
    setLoading(true);
    // ajax request after empty completing
    setTimeout(() => {
      setSelectedRowKeys([]);
      setLoading(false);
    }, 1000);
  };

  const [errors, setErrors] = useState();

  useEffect(() => {
    if (errors && errors.length) {
      errors.map((x) => {
        toast.error(x);
      });
    }
  }, [errors]);

  const createVisitApi = useApi(hospitalsApi.hospitalStaffAction);

  const createVisit = async (id) => {
    setErrors(null);
    await createVisitApi.request({
      action: "CreateVisit",

      dependant: id,
    });
  };

  const handleCreateVisits = () => {
    if (selectedRowKeys && selectedRowKeys.length) {
      console.log("handleCreateVisits", selectedRowKeys);
      for (let i = 0; i < selectedRowKeys.length; i++) {
        createVisit(selectedRowKeys[i]);
      }
    }
  };

  useEffect(() => {
    if (createVisitApi.data && createVisitApi.data.visit) {
      toast.success(createVisitApi.data.response_message);
    }

    if (createVisitApi.data && createVisitApi.data.errors) {
      setErrors(createVisitApi.data.errors);
    }
    console.log("createVisitApi.data", createVisitApi.data);
  }, [createVisitApi.data]);

  const handleFilter = (e) => {
    setsearchText(e.target.value);
    console.log("eeeee", e.target.value);
    const search_param = e.target.value;

    if (search_param && search_param !== "") {
      setdata(
        departmentalVisitors.filter((x) =>
          x.dependant_title.toLowerCase().includes(search_param)
        )
      );
    } else {
      setdata(departmentalVisitors);
    }
  };

  return (
    <div className="grid grid-cols-1 md:grid-cols-12 mt-20 md:mt-2">
      <div className="col-span-2 hidden md:block"></div>
      <div className="col-span-8 bg-gray-50 p-5">
        <ToastContainer theme="colored" position="bottom-center" />
        <CustomInput
          className="w-full h-14 mt-5"
          size="large"
          id="search"
          name="search"
          label="Filter by name"
          placeholder="Filter by name"
          onChange={handleFilter}
          value={searchText}
        />
        <div>
          <Flex className="mt-5" gap="middle" vertical>
            <Flex align="center" justify="space-between" gap="middle">
              <Button
                className="rounded-sm"
                style={{ background: currentColor, color: "white" }}
                type="primary"
                onClick={start}
                disabled={!hasSelected}
                loading={loading}
              >
                Reset
              </Button>
              {hasSelected
                ? `Selected ${selectedRowKeys.length} dependants`
                : null}

              <Button
                className="rounded-sm"
                style={{ background: currentColor, color: "white" }}
                disabled={!selectedRowKeys.length}
                type="primary"
                onClick={handleCreateVisits}
              >
                Confirm
              </Button>
            </Flex>
            <Table
              rowSelection={{
                type: "radio",
                ...rowSelection,
              }}
              columns={columns}
              dataSource={data}
            />

            {openDepartmentToReferModal && (
              <DepartmentToReferModal
                openDepartmentToReferModal={openDepartmentToReferModal}
                setopenDepartmentToReferModal={setopenDepartmentToReferModal}
                selectedRowKeys={selectedRowKeys}
              />
            )}
          </Flex>
        </div>
      </div>
      <div className="col-span-2 hidden md:block"></div>
    </div>
  );
}
